  /* \u2500\u2500 Init pagination on all tables \u2500\u2500 */
  document.querySelectorAll(".rpt-table-wrap").forEach(function(w){
    if(!w.dataset.perPage)w.dataset.perPage="50";
    w.dataset.page="1";
    rptFilter(w.id);
  });
